"""Regression coverage for the declaration protocol used by Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('probability, expected', [(100, 'yes'), (0, 'no')])
def test_faker_decider_defaults(probability, expected):
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker(
                'pybool', locale='en_US',
                truth_probability=factory.LazyFunction(lambda: probability),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory.create_batch(3) == [{'value': expected}] * 3


def test_nested_decider_and_branch_overrides():
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration=factory.Faker('pyint', min_value=1, max_value=1),
            no_declaration=0,
        )

    assert ExampleFactory(value__min_value=7, value__max_value=7) == {'value': 7}
