"""Regression coverage for pre-evaluation of Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('truth_value', [True, False])
def test_faker_decider_defaults_and_unrolled_arguments(truth_value):
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'pybool',
                locale='en_US',
                truth_probability=factory.LazyFunction(
                    lambda: 100 if truth_value else 0),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    for _ in range(2):
        assert ExampleFactory()['result'] == ('yes' if truth_value else 'no')


def test_nested_maybe_decider_and_branch_overrides():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration=factory.Dict({'value': 'default'}),
            no_declaration=None,
        )

    assert ExampleFactory(result__value='override')['result'] == {'value': 'override'}
